def get_nakyung_kor_questions():
    questions = []
    q_counter = 41 # M3_KOR_041 ~ M3_KOR_090
    for p_text, chap, items in NAKYUNG_KOR_PASSAGES:
        for it in items:
            questions.append({
                "question_id": f"M3_KOR_{q_counter:03d}",
                "grade": 3,
                "subject": "국어",
                "chapter": chap,
                "difficulty": "medium" if q_counter % 2 == 1 else "hard",
                "passage": p_text.strip(),
                "question_text": it[0].strip(),
                "options": it[1],
                "correct_answer": it[2],
                "explanation": it[3].strip()
            })
            q_counter += 1
    return questions

if __name__ == "__main__":
    qs = get_nakyung_kor_questions()
    print(f"Generated {len(qs)} questions for Nakyung Korean (IDs {qs[0]['question_id']} ~ {qs[-1]['question_id']})")
